const $=id=>document.getElementById(id);
let project=newProject(),runs=[],truthTables=[],timingMeasurements=[],analogExperiments=[],studyAbort=null,continuousPreparation=null,continuousSession=null,continuousRun=null,continuousSaveAt=0,activeRunId=null,baselineId=null,selection=[],undoStack=[],redoStack=[],saveTimer,saveChain=Promise.resolve(),saveState='saved',saveGeneration=0,runTask=null,preparing=false,truthTableTask=null,selectedEndpoint=null,exampleId=null,reportHTML='',reportURL=null;
