  runs.push(run);activeRunId=run.id;continuousRun=run;continuousSaveAt=0;
  const finish=(state,error)=>{
   if(continuousRun!==run)return;
   run.durationMs=performance.now()-started;run.completedAt=new Date().toISOString();
   if(run.result){run.status='completed-with-warnings';run.result.continuous.sessionStatus=error?'failed-after-window':'stopped';run.result.warnings=[...new Set([...(run.result.warnings??[]),error?`Session ended: ${error.message}. The retained window was completed before that error.`:'Continuous session stopped; the retained window contains completed numerical states.'])];}
   else{run.status=error?(error.status??'failed'):'cancelled';run.error=error?.message??'Stopped before the first result chunk.';}
   if(error)run.logs.push(error.message);
   continuousRun=null;preparing=false;trimRunBudget();renderResults();renderContinuousState();renderDisplayReadouts();scheduleSave(true);status(error?.message??'Continuous simulation stopped. Its recent results are saved; start a new session to initialize the circuit again.');
  };
  const controller=new ContinuousSimulation({onUpdate:result=>{
   if(continuousRun!==run)return;run.result=result;run.engine=result.engine;run.logs=result.logs;run.durationMs=performance.now()-started;
   const start=result.vectors.find(v=>v.name==='time').values[0];for(let i=0;i<2;i++)if(plot.cursors[i]!==null&&plot.cursors[i]<start)plot.cursors[i]=null;
   renderResults();renderContinuousState();renderDisplayReadouts();
   if(performance.now()-continuousSaveAt>2000){continuousSaveAt=performance.now();trimRunBudget();scheduleSave();}
  },onState:(state,error)=>{if(['stopped','failed'].includes(state))finish(state,error);else renderContinuousState();}});
  continuousSession=controller;
  await controller.start(compiled,options);
