async function setupOffline(){
 const label=$('offline-status');
 if(!('serviceWorker' in navigator)||!window.isSecureContext){label.textContent='Offline cache requires HTTPS / localhost';return;}
 try{
  const registration=await navigator.serviceWorker.register(new URL('./sw-'+VERSION+'.js',document.baseURI),{updateViaCache:'none'});
  const watch=worker=>{if(!worker)return;worker.addEventListener('statechange',()=>{
   if(worker.state==='redundant'){label.textContent='Offline cache installation failed';label.title='A required runtime file could not be downloaded or verified. Upload the complete release and use Help to refresh cached application files.';}
   if(worker.state==='installed'&&navigator.serviceWorker.controller){status('An application update is ready. Save a backup, then close and reopen all CircuitBench tabs to use it.');}
  });};
  registration.addEventListener('updatefound',()=>watch(registration.installing));watch(registration.installing);
  await navigator.serviceWorker.ready;
  const target=registration.active??navigator.serviceWorker.controller;
  if(target){
   const channel=new MessageChannel(),timer=setTimeout(()=>{label.textContent='Offline cache could not be checked';channel.port1.close();},5000);
   channel.port1.onmessage=e=>{
    clearTimeout(timer);channel.port1.close();const data=e.data??{};
    if(data.ready&&data.version===VERSION){label.textContent='✓ Offline ready · all runtime assets verified';label.title='';}
    else if(data.ready){label.textContent='Cached update needs a reload';label.title='Close all CircuitBench tabs and reopen the application to use the installed release.';}
    else{label.textContent=data.error?'Offline cache failed verification':'Offline cache is still installing…';label.title=String(data.error??'');}
   };
   target.postMessage({type:'CACHE_STATUS'},[channel.port2]);
  }
 }catch(e){label.textContent='Offline cache unavailable';label.title=e.message;}
}
async function boot(){renderParts();if(innerWidth<701){for(const cls of ['drawer-collapsed','inspector-collapsed']){const collapsed=preference(cls)??(cls==='drawer-collapsed');$('workbench').classList.toggle(cls,collapsed);$(cls==='drawer-collapsed'?'drawer-toggle':'inspector-toggle').setAttribute('aria-expanded',String(!collapsed));}}else{for(const cls of ['drawer-collapsed','inspector-collapsed'])if(preference(cls))$('workbench').classList.add(cls);}if(preference('results-collapsed')){$('results').classList.add('collapsed');$('results-toggle').setAttribute('aria-expanded','false');}try{const stored=await loadCurrent();if(stored){const data=safeEnvelope(stored,validateProject);project=data.project;runs=data.runs;truthTables=data.truthTables;timingMeasurements=data.timingMeasurements;analogExperiments=data.analogExperiments;activeRunId=data.activeRunId;baselineId=data.baselineId;status('Recovered your locally saved project.');}setSaveState('saved');}catch(e){setSaveState('error','! Session only');status(`Local project recovery failed: ${e.message}. Use a downloaded backup to reopen your work.`);}render();requestAnimationFrame(()=>editor.fit());setupOffline();}
boot().catch(handleError);
